INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_PARADISE_CIV','Argentina - The Boy Who Touched Paradise'),
('TXT_KEY_PARADISE_SHORT','The Boy Who Touched Paradise'),
('TXT_KEY_PARADISE_ADJECTIVE','Argentine'),
('TXT_KEY_PARADISE_LEADER','Lionel Messi'),
('TXT_KEY_PARADISE_LEADER_PEDIA','A footballing genius from Rosario whose gifts were apparent long before international fulfillment. This civilization explores brilliance, expectation and redemption as a separate three-act journey.'),
('TXT_KEY_PARADISE_PEDIA','A child, a ball, and a street in Rosario. From these small beginnings came a gift that moved people far beyond football. Greatness endured through joy and disappointment. The ultimate international prize completed a dream; it did not create the genius.'),
('TXT_KEY_PARADISE_STRATEGY','Develop Great People and El Potrero early. Save or spend Dreams on once-per-era magic. In the Renaissance, ease national pressure through real achievements. Recover from the Industrial crisis, reach the Modern Era, earn 40 lifetime Dreams and complete three alternative objectives to build The Last Dance. Culture and Diplomacy are natural choices; every normal victory remains open.'),
('TXT_KEY_PARADISE_UA','He Was Always the Point of Difference'),
('TXT_KEY_PARADISE_UA_HELP','+5% Great Person generation throughout the game; +1 Culture in the capital. Earn Dreams from genuine Great Person births (2), World Wonders (4), the first Golden Age (3), first new City-State alliance (2), and first constructed El Potrero (1) each era. Golden Age and alliance rewards are capped per era; each City-State rewards only its first alliance ever. Complete recovery for 5 Dreams. El Diez performs one 6-Dream Moment of Magic per era. National Pressure begins in the Renaissance; pursue The Last Dance in the Modern Era.'),
('TXT_KEY_PARADISE_EL_DIEZ','El Diez'),
('TXT_KEY_PARADISE_EL_DIEZ_HELP','One unique noncombat hero, created in your first capital. 2 Movement, no maintenance, no production, purchases or expend actions. In an owned city: +2 Culture, +2 Golden Age Points each owner turn and +10% Great Person generation. Returns after five scaled owner turns if lost; no loss rewards. Use The Journey to perform Moments of Magic.'),
('TXT_KEY_PARADISE_EL_DIEZ_PEDIA','The number ten sees a possibility in an ordinary patch of ground. His gift inspires the people around him during every act of the journey.'),
('TXT_KEY_PARADISE_EL_DIEZ_STRATEGY','Station El Diez in a city developing Great People, or move him to the city that needs a Moment of Magic. During recovery, inspire an El Potrero city for eight scaled owner turns as a reliable alternative objective.'),
('TXT_KEY_PARADISE_POTRERO','El Potrero'),
('TXT_KEY_PARADISE_POTRERO_HELP','Replaces the active Amphitheater, preserving its costs, prerequisites, slots and companion effects. Adds +1 Culture and +10% Great Person generation. Your first Production-completed El Potrero each era earns 1 Dream. Purchases and free buildings do not earn Dreams.'),
('TXT_KEY_PARADISE_POTRERO_PEDIA','A humble local football ground, where invention matters more than perfection and a child learns to love the game.'),
('TXT_KEY_PARADISE_POTRERO_STRATEGY','Supports Culture and Great People in every age, and provides a dependable home for the recovery objective.'),
('TXT_KEY_PARADISE_LAST_DANCE','The Last Dance'),
('TXT_KEY_PARADISE_LAST_DANCE_HELP','Unique National Wonder: 450 base Production at Radio (Modern Era). Requires 40 lifetime Dreams and three distinct Journey objectives. Current Dreams are not consumed. Completes The Final Peak once: 15 scaled Golden Age turns, zero Pressure forever, +2 global Happiness, +10% global Culture and Great Person generation, three scaled celebration turns in all current cities, and a capital memorial with +2 Culture/+4 Tourism. Does not grant victory.'),
('TXT_KEY_PARADISE_LAST_DANCE_PEDIA','One final opportunity to turn a lifelong dream into something real. The nation has already witnessed greatness; now it hopes to witness fulfillment.'),
('TXT_KEY_PARADISE_LAST_DANCE_STRATEGY','Review the Final Peak tab for eligibility. Its persistent, alternative objectives recognize your whole game, including Dreams already spent on magic.'),
('TXT_KEY_PARADISE_MEMORIAL','The Eternal Number Ten'),
('TXT_KEY_PARADISE_MEMORIAL_HELP','+2 Culture and +4 Tourism. A unique capital memorial granted at the Final Peak; follows the capital without duplication.'),
('TXT_KEY_PARADISE_CAPITAL','The First Promise'),
('TXT_KEY_PARADISE_PRESENCE','Inspirational Presence'),
('TXT_KEY_PARADISE_PRESSURE_5','The Weight of Expectation'),
('TXT_KEY_PARADISE_PRESSURE_10','A Nation Waiting'),
('TXT_KEY_PARADISE_HOPE','When All Hope Was Lost'),
('TXT_KEY_PARADISE_FULFILLED','The Dream Fulfilled'),
('TXT_KEY_PARADISE_TITLE','THE JOURNEY'),
('TXT_KEY_PARADISE_OVERVIEW','Overview'),
('TXT_KEY_PARADISE_MEMORIES','Memories'),
('TXT_KEY_PARADISE_MAGIC','Moments of Magic'),
('TXT_KEY_PARADISE_PEAK','Final Peak'),
('TXT_KEY_PARADISE_PASS','A Pass Nobody Saw'),
('TXT_KEY_PARADISE_BEAUTY','The Beautiful Game'),
('TXT_KEY_PARADISE_BURDEN_TITLE','THE WEIGHT OF EXPECTATION'),
('TXT_KEY_PARADISE_BURDEN_STORY','The gift is as bright as ever. The streets that once watched in wonder now speak of what it must accomplish. You carry their hope with you. Let real progress make that burden lighter.'),
('TXT_KEY_PARADISE_DENIED_TITLE','A DREAM DENIED'),
('TXT_KEY_PARADISE_DENIED_STORY','The nation felt the dream within reach, and now its uncertain ending is harder to bear. The beauty has not vanished. Give the people a reason to believe again: begin a Golden Age, generate a Great Person, build a World Wonder, form a first alliance, or inspire an El Potrero city for eight scaled owner turns. You have twenty-five scaled owner turns. If this chance passes, another will open.'),
('TXT_KEY_PARADISE_RECOVERY_TITLE','WE RISE AGAIN'),
('TXT_KEY_PARADISE_RECOVERY_STORY','A difficult ending did not become the end of the story. Patient work has made a new beginning possible. The nation remembers the hurt, and also remembers how you answered it.'),
('TXT_KEY_PARADISE_FINAL_TITLE','HE HAS SHAKEN HANDS WITH PARADISE'),
('TXT_KEY_PARADISE_FINAL_STORY','A child once followed a ball through the streets of Rosario. His gift brought wonder long before this night. He carried hope through joyful days and quiet disappointments, and kept creating beauty when certainty disappeared.[NEWLINE][NEWLINE]Now the dream has a shape the whole nation can hold. The trophy completes the wish; it does not explain the genius.[NEWLINE][NEWLINE]The dream is complete. The beauty remains.'),
('TXT_KEY_PARADISE_DAWN','In Rosario, a little boy follows a ball until the street becomes his whole world. Before there are trophies, there is delight: a turn, an unexpected pass, a possibility only he can see. As the gift grows, so does the hope placed upon it. There will be days when brilliance feels effortless, and days when the one dream he wants seems impossibly far away. Yet the love of the game will endure. Lionel Messi, guide Argentina through its own story, and discover how far a beautiful beginning can lead.'),
('TXT_KEY_PARADISE_GREETING','Welcome. There is always another possibility, if we give ourselves time to see it.'),
('TXT_KEY_PARADISE_DEFEAT','We could not finish the dream. But I will remember the beautiful things we made along the way.'),
('TXT_KEY_PARADISE_CITY_0','Buenos Aires'),
('TXT_KEY_PARADISE_CITY_1','Rosario'),
('TXT_KEY_PARADISE_CITY_2','Cordoba'),
('TXT_KEY_PARADISE_CITY_3','Mendoza'),
('TXT_KEY_PARADISE_CITY_4','La Plata'),
